<?php
use App\Views\SearchView;
/** @var \App\ViewModels\SearchPageViewModel $page */
?>
<?php if($page->recent): ?><section class="history"><small>RECENT SEARCHES</small><h2>最近の検索</h2><div class="cards"><?php foreach($page->recent as $recentSearch): ?><?php if($recentSearch['search_type'] === 'flight'): ?><button type="button" class="recent-search-card" data-search-type="flight" data-origin="<?= SearchView::escape($recentSearch['origin']) ?>" data-destination="<?= SearchView::escape($recentSearch['destination']) ?>" data-departure-date="<?= SearchView::escape($recentSearch['departure_date']) ?>" data-return-date="<?= SearchView::escape($recentSearch['return_date'] ?? '') ?>" data-travelers="<?= SearchView::escape($recentSearch['travelers']) ?>"><small class="recent-search-type">✈ 航空券</small><b><?= SearchView::escape($recentSearch['origin']) ?> → <?= SearchView::escape($recentSearch['destination']) ?></b><span><?= SearchView::escape($recentSearch['departure_date']) ?><?= !empty($recentSearch['return_date'])?' 〜 '.SearchView::escape($recentSearch['return_date']):'' ?>・<?= SearchView::escape($recentSearch['travelers']) ?>名</span></button><?php else: ?><button type="button" class="recent-search-card" data-search-type="hotel" data-destination="<?= SearchView::escape($recentSearch['destination']) ?>" data-check-in="<?= SearchView::escape($recentSearch['check_in']) ?>" data-check-out="<?= SearchView::escape($recentSearch['check_out']) ?>" data-adults="<?= SearchView::escape($recentSearch['adults']) ?>" data-children="<?= SearchView::escape($recentSearch['children']) ?>"><small class="recent-search-type">▣ ホテル</small><b><?= SearchView::escape($recentSearch['destination']) ?></b><span><?= SearchView::escape($recentSearch['check_in']) ?> 〜 <?= SearchView::escape($recentSearch['check_out']) ?>・大人<?= SearchView::escape($recentSearch['adults']) ?>名・子供<?= SearchView::escape($recentSearch['children']) ?>名</span></button><?php endif ?><?php endforeach ?></div></section><?php endif ?>
